// Boxes
boxes.forEach((f, i) => {
  const c = [0, 0, 0];
  for (const p of f.pts) { c[0] += p[0] / 4; c[1] += p[1] / 4; c[2] += p[2] / 4; }
  // platform (first 12 faces) sits under everything: draw it in its own earlier layer
  addPoly(f.pts, f.n, c, f.base, f.edge, 0, i < 12 ? 0 : 1);
});
}

