const fs=require('fs');
const src=fs.readFileSync('/tmp/portal_check.js','utf8');
const grad={addColorStop(){}};
const ctx=new Proxy({},{get:(o,k)=>k in o?o[k]:(k.startsWith('create')?()=>grad:()=>{}),set:(o,k,v)=>(o[k]=v,true)});
const el=()=>({getContext:()=>ctx,addEventListener(){},classList:{add(){},remove(){},toggle(){}},setPointerCapture(){},textContent:'',value:'1',width:0,height:0});
const els={};
global.document={getElementById:id=>els[id]||(els[id]=el())};
global.window={innerWidth:1280,innerHeight:720,devicePixelRatio:1,addEventListener(){}};
let n=0,now=0;global.performance={now:()=>now};
global.requestAnimationFrame=f=>{if(n++<200){now+=16;setImmediate(()=>f(now));}else console.log('frames ok; POLYS',els.polys.textContent,'PARTS',els.parts.textContent,'FPS',els.fps.textContent);};
eval(src);
EOF
node /tmp/portal_run.js

